import React, { useEffect, useState } from 'react';
import { fetchBookmarkedPrompts, toggleBookmark } from '../api/prompts';
import PromptCard from '../components/prompts/PromptCard';

const BookMarked = () => {
  const [bookmarkedPrompts, setBookmarkedPrompts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadBookmarks = async () => {
      try {
        const data = await fetchBookmarkedPrompts();
        setBookmarkedPrompts(data);
      } catch (error) {
        console.error('Failed to fetch bookmarks:', error);
      } finally {
        setLoading(false);
      }
    };

    loadBookmarks();
  }, []);

  const handleToggleBookmark = async (promptId) => {
    try {
      await toggleBookmark(promptId);
      // Remove the unbookmarked prompt from the list
      setBookmarkedPrompts((prev) => prev.filter((p) => p._id !== promptId));
    } catch (err) {
      console.error('Failed to toggle bookmark:', err);
    }
  };

  return (
    <div className="container mx-auto px-4 py-6">
      <h2 className="text-2xl font-bold mb-4">📌 Bookmarked Prompts</h2>
      {loading ? (
        <p>Loading...</p>
      ) : bookmarkedPrompts.length === 0 ? (
        <p>No bookmarks found.</p>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {bookmarkedPrompts.map((prompt) => (
            <PromptCard
              key={prompt._id}
              prompt={prompt}
              onToggleBookmark={handleToggleBookmark} // ✅ passed here
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default BookMarked;
